insert into public.exercises (id, nome, modalidade, camera, definicao, equipamento) values
  ('agachamento_livre', 'Agachamento livre', 'forca', 'frontal', '{"id":"agachamento_livre","nome":"Agachamento livre","modalidade":"forca","camera":"frontal","formato":"repeticoes","pontos_obrigatorios":["quadril_e","quadril_d","joelho_e","joelho_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"media","espaco":"3d"},"medidas":{"joelho_2d":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"media","espaco":"2d"},"joelhos_tornozelos":{"tipo":"distancia","pontos":["joelho_e","joelho_d"],"normalizar_por":["tornozelo_e","tornozelo_d"]}},"histerese":5,"fases":[{"nome":"topo","condicao":"medida > 160"},{"nome":"fundo","condicao":"medida < 100"}],"repeticao":["topo","fundo","topo"],"parcial_se":"min_medida < 120","parcial_feedback":"Desça um pouco mais","amplitude":{"extremo":"min","minimo_aceito":100,"ideal":80},"duracao_minima_ms":500,"fase_minima_ms":150,"erros":[{"id":"valgo","condicao":"dist(joelhos) < 0.8 * dist(tornozelos)","fase":"fundo","feedback":"Joelhos para fora"}],"kpis":["reps_validas","reps_parciais","amplitude_media","tempo_excentrico","tempo_concentrico","cadencia"],"variacao_facil":"agachamento_parcial_cadeira","alternativas":{"joelho":"ponte_gluteo"},"instrucoes":["Fique de frente para o celular, com o corpo inteiro na tela.","Pés na largura dos ombros.","Desça até as coxas ficarem paralelas ao chão e suba até estender os joelhos."]}'::jsonb, null),
  ('afundo_alternado', 'Afundo alternado', 'forca', 'lateral', '{"id":"afundo_alternado","nome":"Afundo alternado","modalidade":"forca","camera":"lateral","formato":"repeticoes","pontos_obrigatorios":["quadril","joelho","tornozelo","ombro"],"medida_principal":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"min","espaco":"3d"},"medidas":{"tronco":{"tipo":"inclinacao","pontos":["quadril","ombro"]}},"histerese":5,"fases":[{"nome":"topo","condicao":"medida > 150"},{"nome":"fundo","condicao":"medida < 100"}],"repeticao":["topo","fundo","topo"],"parcial_se":"min_medida < 125","parcial_feedback":"Desça um pouco mais","amplitude":{"extremo":"min","minimo_aceito":100,"ideal":85},"duracao_minima_ms":600,"erros":[{"id":"tronco_inclinado","condicao":"tronco > 30","fase":"fundo","feedback":"Tronco mais reto"}],"kpis":["reps_validas","reps_parciais","amplitude_media","indice_tecnico"],"instrucoes":["Fique de lado para o celular, com o corpo inteiro na tela.","Dê um passo para trás e desça até o joelho de trás chegar perto do chão.","Volte e troque a perna."]}'::jsonb, null),
  ('flexao_braco', 'Flexão de braço', 'forca', 'lateral', '{"id":"flexao_braco","nome":"Flexão de braço","modalidade":"forca","camera":"lateral","formato":"repeticoes","pontos_obrigatorios":["ombro","cotovelo","punho","quadril"],"medida_principal":{"tipo":"angulo","pontos":["ombro","cotovelo","punho"],"lado":"visivel","espaco":"2d"},"medidas":{"alinhamento":{"tipo":"angulo","pontos":["ombro","quadril","tornozelo"],"lado":"visivel","espaco":"2d"},"tronco":{"tipo":"inclinacao","pontos":["quadril","ombro"],"lado":"visivel"}},"histerese":5,"fases":[{"nome":"topo","condicao":"medida > 150 e tronco > 50"},{"nome":"fundo","condicao":"medida < 90 e tronco > 50"}],"repeticao":["topo","fundo","topo"],"parcial_se":"min_medida < 120","parcial_feedback":"Desça mais o peito","amplitude":{"extremo":"min","minimo_aceito":90,"ideal":70},"duracao_minima_ms":600,"erros":[{"id":"quadril_fora","condicao":"alinhamento < 160","feedback":"Alinhe o quadril"}],"kpis":["reps_validas","reps_parciais","amplitude_media","cadencia","indice_tecnico"],"variacao_facil":"flexao_joelhos","instrucoes":["Celular no chão, de lado para você, mostrando o corpo inteiro.","Mãos no chão na linha dos ombros, corpo reto.","Desça até o cotovelo dobrar 90 graus e suba."]}'::jsonb, null),
  ('ponte_gluteo', 'Ponte de glúteo', 'forca', 'lateral', '{"id":"ponte_gluteo","nome":"Ponte de glúteo","modalidade":"forca","camera":"lateral","formato":"repeticoes","pontos_obrigatorios":["ombro","quadril","joelho"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","joelho"],"lado":"visivel","espaco":"2d"},"medidas":{"tronco":{"tipo":"inclinacao","pontos":["quadril","ombro"],"lado":"visivel"}},"histerese":5,"fases":[{"nome":"baixo","condicao":"medida < 130 e tronco > 50"},{"nome":"alto","condicao":"medida > 165"}],"repeticao":["baixo","alto","baixo"],"parcial_se":"max_medida > 148","parcial_feedback":"Suba mais o quadril","amplitude":{"extremo":"max","minimo_aceito":165,"ideal":178},"duracao_minima_ms":600,"erros":[],"kpis":["reps_validas","reps_parciais","amplitude_media"],"instrucoes":["Celular no chão, de lado para você.","Deite de costas, joelhos dobrados e pés no chão.","Suba o quadril até alinhar ombro, quadril e joelho, e desça."]}'::jsonb, null),
  ('prancha', 'Prancha', 'core', 'lateral', '{"id":"prancha","nome":"Prancha","modalidade":"core","camera":"lateral","formato":"isometria","pontos_obrigatorios":["ombro","quadril","tornozelo"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","tornozelo"],"lado":"visivel","espaco":"2d"},"medidas":{"tronco":{"tipo":"inclinacao","pontos":["quadril","ombro"],"lado":"visivel"}},"histerese":4,"sustentacao":{"condicao":"medida > 165 e tronco > 55","feedback_perda":"Alinhe o quadril","controle":{"ponto":"quadril","normalizar_por":["ombro","quadril"],"oscilacao_maxima":0.06}},"erros":[],"kpis":["tempo_valido_s","estabilidade","pct_tempo_valido"],"instrucoes":["Celular no chão, de lado para você.","Apoie as mãos ou os antebraços, corpo reto da cabeça aos pés.","O tempo só corre com o quadril alinhado."]}'::jsonb, null),
  ('polichinelo', 'Polichinelo', 'cardio', 'frontal', '{"id":"polichinelo","nome":"Polichinelo","modalidade":"cardio","camera":"frontal","formato":"repeticoes","pontos_obrigatorios":["ombro_e","ombro_d","quadril_e","quadril_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"distancia","pontos":["tornozelo_e","tornozelo_d"],"normalizar_por":["ombro_e","ombro_d"]},"medidas":{"maos_cabeca":{"tipo":"altura","pontos":["nariz","punho"],"lado":"min","normalizar_por":["ombro_e","ombro_d"]},"maos_ombro":{"tipo":"altura","pontos":["ombro","punho"],"lado":"max","normalizar_por":["ombro_e","ombro_d"]}},"histerese":0.1,"fases":[{"nome":"fechado","condicao":"medida < 1.0 e maos_ombro < 0"},{"nome":"aberto","condicao":"medida > 1.5"}],"repeticao":["fechado","aberto","fechado"],"parcial_se":"max_medida > 1.15","parcial_feedback":"Abra mais as pernas","amplitude":{"extremo":"max","minimo_aceito":1.5,"ideal":2},"duracao_minima_ms":400,"fase_minima_ms":150,"erros":[{"id":"bracos_baixos","quando":"fim_rep","condicao":"max_maos_cabeca < 0","invalida":true,"feedback":"Braços acima da cabeça"}],"kpis":["reps_validas","reps_parciais","cadencia","regularidade"],"variacao_facil":"polichinelo_sem_salto","alternativas":{"joelho":"marcha_estacionaria"},"instrucoes":["Fique de frente para o celular, com o corpo inteiro na tela, inclusive as mãos no alto.","Comece com os pés juntos e os braços ao lado do corpo.","Abra as pernas além da largura dos ombros e leve as mãos acima da cabeça."]}'::jsonb, null),
  ('skipping', 'Skipping (elevação de joelhos)', 'cardio', 'frontal', '{"id":"skipping","nome":"Skipping (elevação de joelhos)","modalidade":"cardio","camera":"frontal","formato":"alternado","pontos_obrigatorios":["ombro_e","ombro_d","quadril_e","quadril_d","joelho_e","joelho_d"],"medida_principal":{"tipo":"altura","pontos":["quadril","joelho"],"lado":"max","normalizar_por":["ombro","quadril"]},"medidas":{"joelho_e_alt":{"tipo":"altura","pontos":["quadril_e","joelho_e"],"normalizar_por":["ombro","quadril"]},"joelho_d_alt":{"tipo":"altura","pontos":["quadril_d","joelho_d"],"normalizar_por":["ombro","quadril"]}},"histerese":0.05,"alternado":{"e":"joelho_e_alt > -0.12","d":"joelho_d_alt > -0.12","quase_e":"joelho_e_alt > -0.45","quase_d":"joelho_d_alt > -0.45"},"parcial_feedback":"Joelho mais alto","duracao_minima_ms":180,"fase_minima_ms":60,"erros":[],"kpis":["reps_validas","reps_parciais","cadencia","simetria"],"instrucoes":["Fique de frente para o celular, com o corpo inteiro na tela.","Corra no lugar levando cada joelho até a altura do quadril."]}'::jsonb, null),
  ('mountain_climber', 'Mountain climber', 'condicionamento', 'lateral', '{"id":"mountain_climber","nome":"Mountain climber","modalidade":"condicionamento","camera":"lateral","formato":"alternado","pontos_obrigatorios":["ombro","quadril","joelho"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","joelho"],"lado":"min","espaco":"3d"},"medidas":{"quadril_e":{"tipo":"angulo","pontos":["ombro_e","quadril_e","joelho_e"],"lado":"e","espaco":"3d"},"quadril_d":{"tipo":"angulo","pontos":["ombro_d","quadril_d","joelho_d"],"lado":"d","espaco":"3d"},"tronco":{"tipo":"inclinacao","pontos":["quadril","ombro"]},"alinhamento":{"tipo":"angulo","pontos":["ombro","quadril","tornozelo"],"lado":"max","espaco":"2d"}},"histerese":5,"alternado":{"e":"quadril_e < 95 e tronco > 45","d":"quadril_d < 95 e tronco > 45"},"duracao_minima_ms":200,"fase_minima_ms":80,"erros":[{"id":"quadril_alto","condicao":"alinhamento < 150 e tronco > 45","feedback":"Abaixe o quadril"}],"kpis":["reps_validas","cadencia","simetria","indice_tecnico"],"instrucoes":["Celular no chão, de lado para você.","Em posição de prancha alta, leve um joelho de cada vez em direção ao peito."]}'::jsonb, null),
  ('elevacao_bracos_y', 'Elevação de braços em Y', 'mobilidade', 'frontal', '{"id":"elevacao_bracos_y","nome":"Elevação de braços em Y","modalidade":"mobilidade","camera":"frontal","formato":"repeticoes","pontos_obrigatorios":["ombro_e","ombro_d","cotovelo_e","cotovelo_d","quadril_e","quadril_d"],"medida_principal":{"tipo":"angulo","pontos":["quadril","ombro","cotovelo"],"lado":"media","espaco":"2d"},"medidas":{"cotovelo":{"tipo":"angulo","pontos":["ombro","cotovelo","punho"],"lado":"min","espaco":"2d"}},"histerese":5,"fases":[{"nome":"baixo","condicao":"medida < 30"},{"nome":"alto","condicao":"medida > 150"}],"repeticao":["baixo","alto","baixo"],"parcial_se":"max_medida > 110","parcial_feedback":"Suba mais os braços","amplitude":{"extremo":"max","minimo_aceito":150,"ideal":170},"duracao_minima_ms":800,"erros":[{"id":"cotovelo_dobrado","condicao":"cotovelo < 150","fase":"alto","feedback":"Estenda os cotovelos"}],"kpis":["reps_validas","reps_parciais","amplitude_media","indice_tecnico"],"instrucoes":["Fique de frente para o celular, com os braços aparecendo inteiros no alto.","Suba os braços estendidos formando um Y e desça devagar."]}'::jsonb, null),
  ('alongamento_posterior', 'Alongamento de posterior em pé', 'alongamento', 'lateral', '{"id":"alongamento_posterior","nome":"Alongamento de posterior em pé","modalidade":"alongamento","camera":"lateral","formato":"isometria","pontos_obrigatorios":["ombro","quadril","joelho","tornozelo"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","joelho"],"lado":"visivel","espaco":"2d"},"medidas":{"joelho":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"visivel","espaco":"2d"}},"histerese":5,"sustentacao":{"condicao":"medida < 110 e joelho > 160","feedback_perda":"Joelhos estendidos, tronco para a frente"},"erros":[],"kpis":["tempo_valido_s","pct_tempo_valido"],"instrucoes":["Fique de lado para o celular.","Com os joelhos estendidos, incline o tronco para a frente e solte os braços.","O tempo corre enquanto você mantém a posição."]}'::jsonb, null),
  ('marcha_estacionaria', 'Marcha estacionária com braços', 'aquecimento', 'frontal', '{"id":"marcha_estacionaria","nome":"Marcha estacionária com braços","modalidade":"aquecimento","camera":"frontal","formato":"alternado","pontos_obrigatorios":["ombro_e","ombro_d","quadril_e","quadril_d","joelho_e","joelho_d"],"medida_principal":{"tipo":"altura","pontos":["quadril","joelho"],"lado":"max","normalizar_por":["ombro","quadril"]},"medidas":{"joelho_e_alt":{"tipo":"altura","pontos":["quadril_e","joelho_e"],"normalizar_por":["ombro","quadril"]},"joelho_d_alt":{"tipo":"altura","pontos":["quadril_d","joelho_d"],"normalizar_por":["ombro","quadril"]}},"histerese":0.05,"alternado":{"e":"joelho_e_alt > -0.5","d":"joelho_d_alt > -0.5","quase_e":"joelho_e_alt > -0.66","quase_d":"joelho_d_alt > -0.66"},"parcial_feedback":"Suba mais o joelho","duracao_minima_ms":250,"fase_minima_ms":100,"erros":[],"kpis":["reps_validas","reps_parciais","cadencia","simetria"],"instrucoes":["Fique de frente para o celular, com o corpo inteiro na tela.","Marche no lugar subindo bem os joelhos e balançando os braços."]}'::jsonb, null),
  ('guerreiro_2', 'Guerreiro II', 'yoga', 'frontal', '{"id":"guerreiro_2","nome":"Guerreiro II","modalidade":"yoga","camera":"frontal","formato":"postura","pontos_obrigatorios":["ombro_e","ombro_d","cotovelo_e","cotovelo_d","quadril_e","quadril_d","joelho_e","joelho_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"min","espaco":"3d"},"medidas":{"ombro_min":{"tipo":"angulo","pontos":["quadril","ombro","cotovelo"],"lado":"min","espaco":"2d"},"ombro_max":{"tipo":"angulo","pontos":["quadril","ombro","cotovelo"],"lado":"max","espaco":"2d"}},"histerese":5,"sustentacao":{"condicao":"medida entre 85 e 125 e ombro_min > 70 e ombro_max < 115","feedback_perda":"Braços na altura dos ombros, joelho da frente dobrado","controle":{"ponto":"quadril","normalizar_por":["ombro","quadril"],"oscilacao_maxima":0.08}},"erros":[],"kpis":["tempo_valido_s","estabilidade","pct_tempo_valido"],"instrucoes":["Fique de frente para o celular, pernas bem afastadas.","Dobre um joelho a 90 graus e abra os braços na altura dos ombros.","Segure. Troque o lado na metade do tempo."]}'::jsonb, null),
  ('postura_arvore', 'Postura da árvore', 'yoga', 'frontal', '{"id":"postura_arvore","nome":"Postura da árvore","modalidade":"yoga","camera":"frontal","formato":"postura","pontos_obrigatorios":["ombro_e","ombro_d","quadril_e","quadril_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"altura","pontos":["tornozelo_d","tornozelo_e"],"normalizar_por":["ombro","quadril"]},"histerese":0.05,"fase_minima_ms":150,"sustentacao":{"condicao":"abs(medida) > 0.25","feedback_perda":"Pé tocou o chão","lado":{"medida":"medida","positivo":"e","negativo":"d"},"controle":{"ponto":"quadril","normalizar_por":["ombro","quadril"],"oscilacao_maxima":0.08}},"erros":[],"kpis":["tempo_valido_s","tempo_valido_e_s","tempo_valido_d_s","estabilidade","simetria"],"instrucoes":["Fique de frente para o celular.","Apoie a planta de um pé na perna de apoio, acima do tornozelo.","Segure. Troque de perna na metade do tempo."]}'::jsonb, null),
  ('cachorro_olhando_baixo', 'Cachorro olhando para baixo', 'yoga', 'lateral', '{"id":"cachorro_olhando_baixo","nome":"Cachorro olhando para baixo","modalidade":"yoga","camera":"lateral","formato":"postura","pontos_obrigatorios":["ombro","quadril","joelho","tornozelo","punho"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","joelho"],"lado":"visivel","espaco":"2d"},"medidas":{"joelho":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"visivel","espaco":"2d"},"cotovelo":{"tipo":"angulo","pontos":["ombro","cotovelo","punho"],"lado":"visivel","espaco":"2d"},"quadril_alto":{"tipo":"altura","pontos":["ombro","quadril"],"lado":"visivel","normalizar_por":["ombro","quadril"]}},"histerese":5,"sustentacao":{"condicao":"medida entre 55 e 105 e joelho > 150 e cotovelo > 155 e quadril_alto > 0.2","feedback_perda":"Quadril para o alto, joelhos e cotovelos estendidos"},"erros":[],"kpis":["tempo_valido_s","pct_tempo_valido"],"instrucoes":["Celular no chão, de lado para você.","Mãos e pés no chão, quadril para o alto, formando um V invertido.","Joelhos e cotovelos estendidos."]}'::jsonb, 'tapete'),
  ('apoio_uma_perna', 'Apoio em uma perna', 'equilibrio', 'frontal', '{"id":"apoio_uma_perna","nome":"Apoio em uma perna","modalidade":"equilibrio","camera":"frontal","formato":"equilibrio","pontos_obrigatorios":["ombro_e","ombro_d","quadril_e","quadril_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"altura","pontos":["tornozelo_d","tornozelo_e"],"normalizar_por":["ombro","quadril"]},"histerese":0.04,"fase_minima_ms":150,"sustentacao":{"condicao":"abs(medida) > 0.15","feedback_perda":"Pé tocou o chão","lado":{"medida":"medida","positivo":"e","negativo":"d"},"controle":{"ponto":"quadril","normalizar_por":["ombro","quadril"],"oscilacao_maxima":0.08}},"erros":[],"kpis":["tempo_valido_s","tempo_valido_e_s","tempo_valido_d_s","oscilacao","estabilidade","simetria"],"variacao_facil":"apoio_uma_perna_com_toque","alternativas":{},"instrucoes":["Fique de frente para o celular, com o corpo inteiro na tela.","Tire um pé do chão e segure. Pode ser qualquer perna.","O tempo só corre enquanto o pé estiver no ar."]}'::jsonb, null),
  ('toque_alvos', 'Toque nos alvos', 'precisao', 'frontal', '{"id":"toque_alvos","nome":"Toque nos alvos","modalidade":"precisao","camera":"frontal","formato":"precisao","pontos_obrigatorios":["ombro_e","ombro_d","punho_e","punho_d"],"medida_principal":{"tipo":"distancia","pontos":["punho_e","punho_d"],"normalizar_por":["ombro_e","ombro_d"]},"alvos":{"pontos":["punho_e","punho_d"],"tempo_ms":2000,"raio":0.45,"intervalo_ms":500},"erros":[],"kpis":["acertos","precisao","tempo_reacao"],"instrucoes":["Fique de frente para o celular, com espaço para abrir os braços.","Um círculo aparece na tela: toque nele com a mão em até 2 segundos."]}'::jsonb, null),
  ('respiracao_guiada', 'Respiração guiada', 'respiracao', 'frontal', '{"id":"respiracao_guiada","nome":"Respiração guiada","modalidade":"respiracao","camera":"frontal","formato":"respiracao","pontos_obrigatorios":["ombro_e","ombro_d"],"medida_principal":{"tipo":"movimento","pontos":["nariz","ombro"],"normalizar_por":["ombro_e","ombro_d"]},"histerese":0.1,"fase_minima_ms":500,"sustentacao":{"condicao":"medida < 0.35","feedback_perda":"Fique parado e respire"},"erros":[],"kpis":["tempo_valido_s","pct_tempo_valido"],"instrucoes":["Sente ou fique em pé, de frente para o celular.","Inspire pelo nariz por 4 segundos e solte o ar por 6.","A câmera só confere se você está parado."]}'::jsonb, null),
  ('agachamento_bastao', 'Agachamento com bastão acima da cabeça', 'mobilidade', 'frontal', '{"id":"agachamento_bastao","nome":"Agachamento com bastão acima da cabeça","modalidade":"mobilidade","camera":"frontal","formato":"repeticoes","pontos_obrigatorios":["quadril_e","quadril_d","joelho_e","joelho_d","tornozelo_e","tornozelo_d"],"medida_principal":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"media","espaco":"3d"},"medidas":{"maos_cabeca":{"tipo":"altura","pontos":["nariz","punho"],"lado":"min","normalizar_por":["ombro_e","ombro_d"]}},"histerese":5,"fases":[{"nome":"topo","condicao":"medida > 160"},{"nome":"fundo","condicao":"medida < 100"}],"repeticao":["topo","fundo","topo"],"parcial_se":"min_medida < 120","parcial_feedback":"Desça um pouco mais","amplitude":{"extremo":"min","minimo_aceito":100,"ideal":80},"duracao_minima_ms":600,"erros":[{"id":"bracos_caem","condicao":"maos_cabeca < 0","feedback":"Bastão acima da cabeça"},{"id":"valgo","condicao":"dist(joelhos) < 0.8 * dist(tornozelos)","fase":"fundo","feedback":"Joelhos para fora"}],"kpis":["reps_validas","reps_parciais","amplitude_media","indice_tecnico"],"instrucoes":["Fique de frente para o celular.","Segure o cabo de vassoura acima da cabeça, braços estendidos.","Agache sem deixar o bastão cair para a frente."]}'::jsonb, 'cabo_vassoura'),
  ('bom_dia_bastao', 'Bom-dia com bastão', 'forca', 'lateral', '{"id":"bom_dia_bastao","nome":"Bom-dia com bastão","modalidade":"forca","camera":"lateral","formato":"repeticoes","pontos_obrigatorios":["ombro","quadril","joelho","tornozelo"],"medida_principal":{"tipo":"angulo","pontos":["ombro","quadril","joelho"],"lado":"visivel","espaco":"2d"},"medidas":{"joelho":{"tipo":"angulo","pontos":["quadril","joelho","tornozelo"],"lado":"visivel","espaco":"2d"}},"histerese":5,"fases":[{"nome":"topo","condicao":"medida > 165"},{"nome":"fundo","condicao":"medida < 110"}],"repeticao":["topo","fundo","topo"],"parcial_se":"min_medida < 135","parcial_feedback":"Incline mais o tronco","amplitude":{"extremo":"min","minimo_aceito":110,"ideal":90},"duracao_minima_ms":800,"erros":[{"id":"joelhos_dobrados","condicao":"joelho < 150","fase":"fundo","feedback":"Joelhos quase estendidos"}],"kpis":["reps_validas","reps_parciais","amplitude_media","indice_tecnico"],"instrucoes":["Fique de lado para o celular, com o bastão apoiado nas costas.","Incline o tronco para a frente com os joelhos quase estendidos e volte."]}'::jsonb, 'cabo_vassoura')
